// Idempotency key + in-run dedupe guard.
// Cannibalized from template-3297 ("Merge - Keep only new items" diff/dedupe), reduced to a
// STATELESS form: this activity body keeps no state between runs (wrap = activity principle).
// Cross-run dedupe is the platform custody door's job: it derives run IDs from the object key,
// so re-POSTing the same idempotency_key is a no-op there (standing idempotency rule).
// NOTE: no require() anywhere - pure JS FNV-1a so the node works regardless of
// NODE_FUNCTION_ALLOW_BUILTIN on the instance.
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('00000000' + h.toString(16)).slice(-8);
}

const seen = new Set();
const out = [];
const nowMs = Date.now();

for (const item of $input.all()) {
  const j = item.json || {};
  const bin = (item.binary && item.binary.data) || {};
  const path = j.path || j.fileName || bin.fileName || '';
  // fileSize is a display string from Read/Write Files From Disk (e.g. "12.3 kB");
  // fileSizeBytes is not guaranteed, so both are folded into the key material.
  const sizeRaw = String(bin.fileSize != null ? bin.fileSize : (j.size != null ? j.size : ''));
  const keyMaterial = path + '|' + sizeRaw;
  const idempotencyKey = 'dropdir-' + fnv1a(keyMaterial) + '-' + fnv1a(path);

  if (seen.has(idempotencyKey)) { continue; }   // duplicate inside THIS batch only
  seen.add(idempotencyKey);

  out.push({
    json: {
      idempotency_key: idempotencyKey,
      source_path: path,
      source_size_display: sizeRaw,
      source_mime: bin.mimeType || null,
      trigger_event: j.event || 'add',
      // TEMPORAL MANDATE: epoch-numeric + ISO ride through every payload, every hop.
      observed_at_epoch_ms: nowMs,
      observed_at_iso: new Date(nowMs).toISOString(),
      pipeline_stage: 'intake.dropdir',
      activity_name: 'n8n.intake.dropdir',       // 1:1 with the Temporal activity (Stage 5)
    },
    binary: item.binary,
  });
}

return out;
